import type { FocusEvent } from 'react'
import { Meta, StoryObj } from '@storybook/react-vite'
import { useArgs, useState } from 'storybook/preview-api'
import { SupportMessage } from '../../SupportMessage'
import { TextInput, TextInputProps } from '../TextInput'

const meta: Meta<TextInputProps> = {
  title: 'TextInput',
  component: TextInput,
}

export default meta
type Story = StoryObj<TextInputProps>

const InteractiveTemplate = (args: TextInputProps) => {
  const [{ value }, updateArgs] = useArgs<TextInputProps>()
  // Typing stays in local state. Writing every keystroke into args rewrites the
  // URL and re-renders the controls, which makes typing laggy in Storybook.
  const [draft, setDraft] = useState<string | null>(null)

  const handleChange = (e: string) => {
    setDraft(e)
    args?.onChange?.(e)
  }

  const handleBlur = (e: FocusEvent<HTMLInputElement>) => {
    if (draft !== null) {
      updateArgs({ value: draft })
      setDraft(null)
    }
    args?.onBlur?.(e)
  }

  return (
    <TextInput
      {...args}
      value={draft ?? value ?? ''}
      onChange={handleChange}
      onBlur={handleBlur}
    />
  )
}

export const Default: Story = {
  args: {
    name: 'textInput',
    placeholder: 'Placeholder text',
  },
  render: InteractiveTemplate,
}

export const DefaultFallback: Story = {
  args: {
    id: 'textInput2',
    name: 'textInput',
    placeholder: 'Placeholder text',
    fallbackStyle: true,
  },
  render: InteractiveTemplate,
}

const LocalStateTemplate = (args: TextInputProps) => {
  const [value, setValue] = useState(args.value ?? '')

  return <TextInput {...args} value={value} onChange={setValue} />
}

